// Balance is the resolver for the balance field.
func (r *queryResolver) Balance(ctx context.Context, addr string) (string, error) {
	// This function sums the recorded outstanding balances against
	// the currently spendable amounts. The currently spendable
	// amounts are amounts that were earmarked to be spent,
	// which when they are designated are immediately consumed
	// as such.
	if !ethCommon.IsHexAddress(addr) {
		return "", fmt.Errorf("not valid address")
	}
	addr_ := ethCommon.HexToAddress(addr)
	accAddr := acc_types.GetClientAddr(r.AccountsFactoryAddr, addr_)
	row := r.Db.QueryRow(`
SELECT rfqhub_events_balance_changed($1, $2)`,
		accAddr.String(),
		acc_types.AssetUsdc,
	)
	var amt events.Number
	if err := row.Scan(&amt).Error; err != nil {
		slog.Error("Failed to scan the get spendable row",
			"err", err,
		)
		return "", fmt.Errorf("spendable error")
	}
	return amt.String(), nil
}

// OpenAuctions is the resolver for the openAuctions field.
func (r *queryResolver) OpenAuctions(ctx context.Context) (*model.OpenAuctions, error) {
	rows, err := r.Db.Query(`
SELECT acc_addr, amt, is_up, price_target, outcome, expiry, id
FROM rfqhub_bundles_taker_ongoing_1`,
	)
	if err != nil {
		slog.Error("Error retrieving ongoing bundles", "err", err)
		return nil, fmt.Errorf("error receiving ongoing bundles")
	}
	defer rows.Close()
	openAuctions := model.OpenAuctions{
		ID: fmt.Sprintf("auctions %v", time.Now()),
	}
	for rows.Next() {
		o := new(model.OpenAuction)
		var (
			openToBeWon, priceTarget uint64
			expiry                   time.Time
		)
		err = rows.Scan(
			&o.AccAddr,
			&openToBeWon,
			&o.IsUp,
			&priceTarget,
			&o.Outcome,
			&expiry,
			&o.BundleTakerID,
		)
		if err != nil {
			slog.Error("Error scanning open auctions", "err", err)
			return nil, fmt.Errorf("scanning open auctions")
		}
		o.OpenToBeWon = strconv.FormatUint(openToBeWon, 10)
		o.PriceTarget = strconv.FormatUint(priceTarget, 10)
		o.ExpiryTs = int(expiry.Unix())
		openAuctions.OpenAuctions = append(openAuctions.OpenAuctions, o)
	}
	return &openAuctions, nil
}

